/* Bloom — catalogue seed, generated from PRODUCTS in js/data.js.
   18 rows: 8 beans, 7 tools, 3 machines.
   Regenerate rather than hand-edit, so the file and the shop agree. */

insert into products (
  id, category, icon, sort_order,
  name_en, name_ar, origin_en, origin_ar,
  notes_en, notes_ar, desc_en, desc_ar, unit_en, unit_ar,
  price_fils, stock, tags, specs, recipe, bag_colour, model, image
) values
  ('eth-guji', 'beans', null, 0, 'Hambela Washed', 'همبيلا مغسولة', 'Ethiopia · Guji', 'إثيوبيا · قوجي', 'Jasmine and ripe peach over black tea. Light-roasted for filter — the clean, floral classic.', 'ياسمين وخوخ ناضج فوق شاي أسود. تحميص فاتح للتقطير — النقي الزهري الكلاسيكي.', 'Fully washed at the Hambela mill and dried on raised beds at 2050 m, which is why the cup arrives so clear. Jasmine on the nose, ripe peach in the body, and a black-tea dryness in the finish that keeps it drinkable to the last mouthful. We roast it light on Tuesdays and rest it three days. It is the bean we hand anyone brewing pour-over for the first time.', 'تُغسل كاملاً في معمل همبيلا وتُجفَّف على أسِرَّة مرتفعة عند 2050 متراً، ولهذا يأتي الفنجان بهذا الصفاء. ياسمين في الأنف، وخوخ ناضج في الجسم، وجفاف الشاي الأسود في النهاية يجعلها قابلة للشرب حتى آخر جرعة. نحمّصها فاتحة كل ثلاثاء وتستريح ثلاثة أيام. هذه أول حبة نرشّحها لمن يبدأ بالتقطير.', '250 g', '٢٥٠ غم', 6500, 12, array['classic','filter']::text[], '{"process":{"en":"Washed","ar":"مغسولة"},"altitude":{"en":"2050 m","ar":"2050 م"},"roast":{"en":"Filter","ar":"تقطير"},"varietal":{"en":"Heirloom","ar":"أصناف محلية"},"harvest":{"en":"Nov 2025","ar":"نوفمبر 2025"}}'::jsonb, '{"method":"filter","methodName":{"en":"V60 pour-over","ar":"تقطير V60"},"dose":15,"water":250,"temp":93,"bloom":30,"bloomTime":30,"total":"2:45","grind":{"en":"Medium-fine","ar":"وسط ناعم"}}'::jsonb, '{"body":"#57683F","top":"#3D4B2C"}'::jsonb, 'v60', 'assets/eth-guji.svg'),
  ('col-huila', 'beans', null, 1, 'El Mirador Natural', 'إل ميرادور طبيعية', 'Colombia · Huila', 'كولومبيا · هويلا', 'Red cherry and cane sugar with apple skin. Natural process — juicy, sweet and forgiving.', 'كرز أحمر وسكر قصب مع قشر تفاح. معالجة طبيعية — عصيرية وحلوة ومتسامحة.', 'Picked ripe on a smallholding above Pitalito and dried whole for eighteen days, turned by hand every few hours. That slow drying is what pushes the red cherry forward without letting it tip into ferment. Sweet enough to drink black all afternoon, and it will forgive a pour that wanders. Brew it a degree cooler than the Ethiopian.', 'تُقطف ناضجة في حيازة صغيرة فوق بيتاليتو وتُجفَّف كاملة ثمانية عشر يوماً، وتُقلَّب يدوياً كل ساعات. هذا التجفيف البطيء هو ما يُبرز الكرز الأحمر دون أن ينقلب إلى تخمّر. حلاوتها تكفي لشربها سادة طول العصر، وهي تتسامح مع صبّ متعثّر. حضّرها بدرجة أبرد من الإثيوبية.', '250 g', '٢٥٠ غم', 6000, 20, array['fruity','filter']::text[], '{"process":{"en":"Natural","ar":"طبيعية"},"altitude":{"en":"1750 m","ar":"1750 م"},"roast":{"en":"Filter","ar":"تقطير"},"varietal":{"en":"Caturra","ar":"كاتورا"},"harvest":{"en":"Oct 2025","ar":"أكتوبر 2025"}}'::jsonb, '{"method":"filter","methodName":{"en":"V60 pour-over","ar":"تقطير V60"},"dose":15,"water":250,"temp":92,"bloom":30,"bloomTime":30,"total":"3:00","grind":{"en":"Medium","ar":"وسط"}}'::jsonb, '{"body":"#AC5334","top":"#7E3722"}'::jsonb, 'v60', 'assets/col-huila.svg'),
  ('yem-haraz', 'beans', null, 2, 'Haraz Terraces', 'مدرّجات حراز', 'Yemen · Haraz', 'اليمن · حراز', 'Dark chocolate and dried fig with warm spice. Deep and traditional — excellent as espresso.', 'شوكولاتة داكنة وتين مجفف مع بهار دافئ. عميقة وتقليدية — ممتازة كإسبريسو.', 'Terraced smallholder plots at 2200 m in the Haraz mountains, sun-dried on rooftops the way they have been for centuries. Heavy in the mouth, low in acidity, and unmistakably Yemeni: dark chocolate first, then dried fig, then a long spiced finish. Pulled as espresso it tastes of fig and cardamom; brewed as filter it turns to cocoa.', 'مدرّجات صغيرة على ارتفاع 2200 متر في جبال حراز، تُجفَّف شمساً على الأسطح كما جرت العادة منذ قرون. ثقيلة في الفم، قليلة الحموضة، ويمنية بلا التباس: شوكولاتة داكنة أولاً، ثم تين مجفف، ثم نهاية طويلة مبهّرة. كإسبريسو تعطي التين والهيل، وكقطرة تتحوّل إلى كاكاو.', '250 g', '٢٥٠ غم', 14000, 6, array['classic','espresso']::text[], '{"process":{"en":"Natural","ar":"طبيعية"},"altitude":{"en":"2200 m","ar":"2200 م"},"roast":{"en":"Espresso","ar":"إسبريسو"},"varietal":{"en":"Udaini","ar":"عُديني"},"harvest":{"en":"Sep 2025","ar":"سبتمبر 2025"}}'::jsonb, '{"method":"filter","methodName":{"en":"V60 pour-over","ar":"تقطير V60"},"dose":16,"water":250,"temp":94,"bloom":32,"bloomTime":30,"total":"3:10","grind":{"en":"Medium","ar":"وسط"}}'::jsonb, '{"body":"#241A14","top":"#0F0A07"}'::jsonb, 'v60', 'assets/yem-haraz.svg'),
  ('ken-nyeri', 'beans', null, 3, 'Gichathaini AA', 'جيتشاثايني AA', 'Kenya · Nyeri', 'كينيا · نيري', 'Blackcurrant and grapefruit over plum and brown sugar. Sharp, structured, unmistakably Kenyan.', 'كشمش أسود وجريب فروت فوق برقوق وسكر بني. حادّة ومتماسكة وكينية بلا التباس.', 'AA screen from the Gichathaini factory in Nyeri, double-fermented in water and dried slowly on beds at 1800 m. Kenyan coffee at its most itself: blackcurrant that borders on savoury, grapefruit acidity with real structure behind it, and brown sugar underneath holding it together. Grind a touch coarser than you think — this one gets astringent if you over-extract it.', 'حجم AA من معمل جيتشاثايني في نيري، تُخمَّر مرتين في الماء وتُجفَّف ببطء على الأسِرَّة عند 1800 متر. القهوة الكينية في أصدق صورها: كشمش أسود يقارب المالح، وحموضة جريب فروت بهيكل حقيقي خلفها، وسكر بني تحتها يجمع الأمر. اطحن أخشن قليلاً مما تتوقّع — فهذه تصبح قابضة إن أفرطت في الاستخلاص.', '250 g', '٢٥٠ غم', 8500, 9, array['fruity','filter']::text[], '{"process":{"en":"Washed, double-fermented","ar":"مغسولة، تخمير مزدوج"},"altitude":{"en":"1800 m","ar":"1800 م"},"roast":{"en":"Filter","ar":"تقطير"},"varietal":{"en":"SL28 · SL34","ar":"SL28 · SL34"},"harvest":{"en":"Jan 2026","ar":"يناير 2026"}}'::jsonb, '{"method":"filter","methodName":{"en":"V60 pour-over","ar":"تقطير V60"},"dose":15,"water":250,"temp":94,"bloom":30,"bloomTime":30,"total":"2:50","grind":{"en":"Medium","ar":"وسط"}}'::jsonb, '{"body":"#8C3B44","top":"#5E252C"}'::jsonb, 'v60', 'assets/ken-nyeri.svg'),
  ('bra-cerrado', 'beans', null, 4, 'Fazenda Rio Verde', 'فازيندا ريو فيردي', 'Brazil · Cerrado', 'البرازيل · سيرادو', 'Hazelnut and milk chocolate with caramel. Low acidity, thick body — the everyday espresso.', 'بندق وشوكولاتة بالحليب مع كراميل. حموضة منخفضة وجسم سميك — إسبريسو كل يوم.', 'Pulped natural from the Cerrado plateau at 1100 m, where the dry harvest lets the fruit come off cleanly and leaves the sugars behind. Hazelnut and milk chocolate, almost no acidity, and a body thick enough to carry milk without disappearing into it. This is the one we keep in the hopper: cheap enough to drink daily and sweet enough that you want to.', 'معالجة نصف طبيعية من هضبة سيرادو عند 1100 متر، حيث يسمح الحصاد الجاف بإزالة الفاكهة بنظافة ويُبقي السكريات. بندق وشوكولاتة بالحليب، بلا حموضة تقريباً، وجسم سميك يحمل الحليب دون أن يذوب فيه. هذه ما نُبقيها في القادوس: رخيصة تكفي لشربها يومياً وحلوة تكفي لترغب في ذلك.', '250 g', '٢٥٠ غم', 5000, 26, array['classic','espresso']::text[], '{"process":{"en":"Pulped natural","ar":"نصف طبيعية"},"altitude":{"en":"1100 m","ar":"1100 م"},"roast":{"en":"Espresso","ar":"إسبريسو"},"varietal":{"en":"Yellow Catuaí","ar":"كاتواي أصفر"},"harvest":{"en":"Aug 2025","ar":"أغسطس 2025"}}'::jsonb, '{"method":"filter","methodName":{"en":"V60 pour-over","ar":"تقطير V60"},"dose":16,"water":250,"temp":95,"bloom":32,"bloomTime":30,"total":"3:15","grind":{"en":"Medium-coarse","ar":"وسط خشن"}}'::jsonb, '{"body":"#8A6A3F","top":"#5F4826"}'::jsonb, 'v60', 'assets/bra-cerrado.svg'),
  ('gua-huehue', 'beans', null, 5, 'Finca La Bolsa', 'فينكا لا بولسا', 'Guatemala · Huehuetenango', 'غواتيمالا · ويويتينانغو', 'Caramel and red apple with cocoa and orange peel. Balanced, round, good every way you brew it.', 'كراميل وتفاح أحمر مع كاكاو وقشر برتقال. متوازنة وممتلئة، وجيدة بأي طريقة تحضّرها.', 'Washed and sun-dried at 1900 m in the dry highland air of Huehuetenango, which lets the drying finish evenly and slowly. Caramel and red apple up front, cocoa underneath, and a twist of orange peel as it cools. The most even-tempered coffee on the shelf: it is good as filter, good as espresso, and good the next morning if you forgot about it.', 'مغسولة ومجفّفة شمساً عند 1900 متر في هواء مرتفعات ويويتينانغو الجاف، مما يجعل التجفيف يكتمل بانتظام وبطء. كراميل وتفاح أحمر في المقدّمة، وكاكاو تحتهما، ولمسة قشر برتقال حين تبرد. أكثر قهوة متوازنة على الرف: جيدة تقطيراً، وجيدة إسبريسو، وجيدة صباح الغد إن نسيتها.', '250 g', '٢٥٠ غم', 7000, 15, array['classic','filter']::text[], '{"process":{"en":"Washed","ar":"مغسولة"},"altitude":{"en":"1900 m","ar":"1900 م"},"roast":{"en":"Filter","ar":"تقطير"},"varietal":{"en":"Bourbon · Caturra","ar":"بوربون · كاتورا"},"harvest":{"en":"Mar 2026","ar":"مارس 2026"}}'::jsonb, '{"method":"filter","methodName":{"en":"V60 pour-over","ar":"تقطير V60"},"dose":15,"water":250,"temp":93,"bloom":30,"bloomTime":30,"total":"2:55","grind":{"en":"Medium-fine","ar":"وسط ناعم"}}'::jsonb, '{"body":"#6B4A2E","top":"#48301C"}'::jsonb, 'v60', 'assets/gua-huehue.svg'),
  ('cri-tarrazu', 'beans', null, 6, 'Las Lajas Honey', 'لاس لاخاس هني', 'Costa Rica · Tarrazú', 'كوستاريكا · تارّازو', 'Honey and peach with plum and cane sugar. Syrupy sweetness from the honey process.', 'عسل وخوخ مع برقوق وسكر قصب. حلاوة كالشراب من المعالجة العسلية.', 'A yellow honey: the skin comes off but the sticky mucilage stays on through drying, so the sugars work their way back into the bean. The result is syrupy in a way washed coffee never is — honey and peach, plum as it cools, cane sugar all the way through. Dried twelve days at 1500 m in Tarrazú, turned every two hours.', 'عسلية صفراء: تُزال القشرة ويبقى اللبّ اللزج طوال التجفيف، فتعود السكريات إلى الحبة. والنتيجة قوامها كالشراب بشكل لا تصله المغسولة أبداً — عسل وخوخ، وبرقوق حين تبرد، وسكر قصب من البداية للنهاية. جُفِّفت اثني عشر يوماً عند 1500 متر في تارّازو، وقُلِّبت كل ساعتين.', '250 g', '٢٥٠ غم', 7500, 11, array['fruity','filter']::text[], '{"process":{"en":"Yellow honey","ar":"عسلية صفراء"},"altitude":{"en":"1500 m","ar":"1500 م"},"roast":{"en":"Filter","ar":"تقطير"},"varietal":{"en":"Caturra · Villalobos","ar":"كاتورا · فيلالوبوس"},"harvest":{"en":"Feb 2026","ar":"فبراير 2026"}}'::jsonb, '{"method":"filter","methodName":{"en":"V60 pour-over","ar":"تقطير V60"},"dose":15,"water":250,"temp":92,"bloom":30,"bloomTime":30,"total":"3:05","grind":{"en":"Medium","ar":"وسط"}}'::jsonb, '{"body":"#B07A3C","top":"#7E5322"}'::jsonb, 'v60', 'assets/cri-tarrazu.svg'),
  ('rwa-nyamasheke', 'beans', null, 7, 'Kanzu Washed', 'كانزو مغسولة', 'Rwanda · Nyamasheke', 'رواندا · نياماشيكي', 'Rose and lime over blackcurrant and honey. Delicate, floral, and very clean in the cup.', 'ورد وليمون أخضر فوق كشمش أسود وعسل. رقيقة وزهرية ونظيفة جداً في الفنجان.', 'From the Kanzu washing station in Nyamasheke, on the hills above Lake Kivu at 1700 m. Fully washed and soaked overnight in clean water, which is what gives it that glassy clarity. Rose and lime arrive first, blackcurrant sits behind them, and honey rounds off the finish. Delicate enough that a coarse grind or cool water will hide it — brew this one carefully.', 'من محطة غسل كانزو في نياماشيكي، على التلال فوق بحيرة كيفو عند 1700 متر. تُغسل كاملاً وتُنقع ليلة في ماء نظيف، وهذا ما يمنحها صفاءً زجاجياً. يأتي الورد والليمون الأخضر أولاً، ويجلس الكشمش الأسود خلفهما، ويُدوّر العسل النهاية. رقيقة لدرجة أن طحناً خشناً أو ماءً بارداً سيخفيها — حضّر هذه بعناية.', '250 g', '٢٥٠ غم', 7000, 13, array['fruity','filter']::text[], '{"process":{"en":"Washed, overnight soak","ar":"مغسولة، نقع ليلي"},"altitude":{"en":"1700 m","ar":"1700 م"},"roast":{"en":"Filter","ar":"تقطير"},"varietal":{"en":"Red Bourbon","ar":"بوربون أحمر"},"harvest":{"en":"Dec 2025","ar":"ديسمبر 2025"}}'::jsonb, '{"method":"filter","methodName":{"en":"V60 pour-over","ar":"تقطير V60"},"dose":15,"water":250,"temp":93,"bloom":30,"bloomTime":30,"total":"2:45","grind":{"en":"Medium-fine","ar":"وسط ناعم"}}'::jsonb, '{"body":"#5E7060","top":"#3F4E42"}'::jsonb, 'v60', 'assets/rwa-nyamasheke.svg'),
  ('dripper-v60', 'tools', 'dripper', 8, 'Cone dripper', 'قمع التقطير', 'Dripper', 'قمع', 'V60 and flat-bottom cones in ceramic, glass or plastic.', 'أقماع V60 ومسطحة القاعدة من السيراميك أو الزجاج أو البلاستيك.', 'A 60° cone with spiral ribs, so the paper never seals against the wall and the bed drains evenly. Ceramic holds heat best; plastic is the one to travel with.', 'قمع بزاوية ٦٠° وأخاديد حلزونية، فلا تلتصق الورقة بالجدار ويصرّف القاع بانتظام. السيراميك يحفظ الحرارة أفضل، والبلاستيك أنسب للسفر.', 'size 02', 'مقاس ٠٢', 4500, 30, array['brewing']::text[], '{"material":{"en":"Ceramic · glass · plastic","ar":"سيراميك · زجاج · بلاستيك"},"size":{"en":"02 · 1–4 cups","ar":"٠٢ · 1–4 فناجين"},"ribs":{"en":"Spiral, 60° cone","ar":"حلزونية، قمع 60°"}}'::jsonb, null, null, 'v60', 'assets/dripper.svg'),
  ('filter-papers', 'tools', 'paper', 9, 'Filter papers', 'أوراق الترشيح', 'Filter papers', 'أوراق', 'Bleached and natural, sizes 01 and 02, 100-packs.', 'مبيّضة وطبيعية، مقاسا ٠١ و٠٢، عبوات ١٠٠ ورقة.', 'Rinse them first, always — a dry paper tastes of paper and cools the cone. Bleached brews cleaner; natural adds a faint hint of card.', 'اغسلها أولاً دائماً — الورقة الجافة تُشعر بطعم الورق وتبرّد القمع. المبيّضة أنقى في الكوب، والطبيعية تضيف لمسة كرتونية خفيفة.', '100 pack', 'عبوة ١٠٠', 1750, 80, array['brewing']::text[], '{"size":{"en":"01 · 02","ar":"٠١ · ٠٢"},"finish":{"en":"Bleached / natural","ar":"مبيّضة / طبيعية"},"count":{"en":"100 sheets","ar":"100 ورقة"}}'::jsonb, null, null, null, 'assets/paper.svg'),
  ('hand-grinder', 'tools', 'grinder', 10, 'Manual grinder', 'مطحنة يدوية', 'Manual grinder', 'مطحنة', 'Stainless burrs with click adjustment for filter and espresso.', 'مطاحن ستانلس بتدريج نقري للتقطير والإسبريسو.', 'Conical steel burrs on a double bearing, so the shaft does not wobble and the grind stays even. Thirty clicks from espresso to French press; filter sits around click 18.', 'مطاحن مخروطية من الفولاذ على محملين، فلا يتأرجح العمود ويبقى الطحن متساوياً. ثلاثون نقرة من الإسبريسو إلى الفرنسية، والتقطير عند النقرة ١٨ تقريباً.', '1 pc', 'حبة', 22000, 14, array['grinding']::text[], '{"burrs":{"en":"48 mm stainless conical","ar":"مخروطية ستانلس 48 مم"},"steps":{"en":"30 clicks · 22 µm each","ar":"30 نقرة · 22 ميكرون لكل نقرة"},"capacity":{"en":"30 g","ar":"30 غم"}}'::jsonb, null, null, 'grinder', 'assets/grinder.svg'),
  ('gooseneck-kettle', 'tools', 'kettle', 11, 'Gooseneck kettle', 'غلاية رقبة الإوزة', 'Kettle', 'غلاية', 'Variable temperature, slow controlled pour, 0.6–1 L.', 'حرارة متغيّرة وصبّ بطيء محكوم، 0.6–1 لتر.', 'The narrow spout is the whole point: it turns your wrist into a flow-rate control. Set it to 93 °C and it holds there while you pour.', 'الفوهة الضيقة هي الفكرة كلها: تحوّل معصمك إلى منظّم لسرعة الصبّ. اضبطها على 93 °م وتثبت عندها أثناء الصبّ.', '0.8 L', '٠٫٨ لتر', 34000, 9, array['brewing']::text[], '{"capacity":{"en":"0.6–1.0 L","ar":"0.6–1.0 لتر"},"range":{"en":"40–100 °C","ar":"40–100 °م"},"hold":{"en":"±1 °C for 60 min","ar":"±1 °م لمدة 60 دقيقة"}}'::jsonb, null, null, 'kettle', 'assets/kettle.svg'),
  ('digital-scale', 'tools', 'scale', 12, 'Digital scale', 'ميزان رقمي', 'Scale', 'ميزان', '0.1 g accuracy with a built-in timer for the bloom.', 'دقة 0.1 غم مع مؤقّت مدمج لمرحلة التفتّح.', 'Weigh the coffee, weigh the water, watch the clock — that is most of brewing. The timer starts itself at the first drop, which is exactly when the bloom begins.', 'زِن البنّ، زِن الماء، وراقب الوقت — هذا معظم التحضير. يبدأ المؤقّت تلقائياً مع أول قطرة، وهي لحظة بدء التفتّح.', '1 pc', 'حبة', 12500, 18, array['weighing']::text[], '{"accuracy":{"en":"0.1 g","ar":"0.1 غم"},"capacity":{"en":"2000 g","ar":"2000 غم"},"timer":{"en":"Auto-start at first drop","ar":"بدء تلقائي مع أول قطرة"}}'::jsonb, null, null, 'scale', 'assets/scale.svg'),
  ('thermometer', 'tools', 'thermometer', 13, 'Probe thermometer', 'ميزان حرارة', 'Thermometer', 'حرارة', 'Instant read, 0–100 °C — brew at 92–94 °C.', 'قراءة فورية، 0–100 °م — حضّر عند 92–94 °م.', 'For any kettle without a thermostat. Boil, wait, probe: water off the boil drops roughly a degree every twenty seconds in a Kuwait kitchen.', 'لأي غلاية بلا منظّم حرارة. اغلِ، انتظر، ثم اقرأ: الماء بعد الغليان ينزل درجة كل عشرين ثانية تقريباً في مطبخ كويتي.', '1 pc', 'حبة', 6000, 25, array['weighing']::text[], '{"range":{"en":"0–100 °C","ar":"0–100 °م"},"accuracy":{"en":"±0.5 °C","ar":"±0.5 °م"},"readtime":{"en":"2 s","ar":"2 ثانية"}}'::jsonb, null, null, null, 'assets/thermometer.svg'),
  ('glass-server', 'tools', 'server', 14, 'Glass server', 'دورق زجاجي', 'Server', 'دورق', 'Heat-proof glass carafes, 400 and 600 ml, with markings.', 'دوارق زجاج مقاوم للحرارة، 400 و600 مل، بتدريجات.', 'Borosilicate, marked every 100 ml so you can read the brew without a scale. Warm it with the paper rinse and the cup lands hotter.', 'زجاج بوروسيليكات مدرّج كل 100 مل، فتقرأ الكمية بلا ميزان. سخّنه بماء غسل الورقة ليصل الفنجان أسخن.', '600 ml', '٦٠٠ مل', 7500, 22, array['brewing']::text[], '{"volume":{"en":"400 / 600 ml","ar":"400 / 600 مل"},"glass":{"en":"Borosilicate","ar":"بوروسيليكات"},"markings":{"en":"Every 100 ml","ar":"كل 100 مل"}}'::jsonb, null, null, null, 'assets/server.svg'),
  ('espresso-machine', 'machines', 'espresso', 15, 'Espresso machine', 'مكينة إسبريسو', 'Espresso', 'إسبريسو', 'Single boiler to dual boiler, 9 bar, PID temperature control.', 'من سخّان واحد إلى سخّانين، 9 بار، وتحكّم PID بالحرارة.', 'A 58 mm group and a real PID, which is what separates a repeatable shot from a lucky one. Brew and steam at once, and a 30-minute warm-up before the first cup.', 'رأس 58 مم ومنظّم PID حقيقي، وهذا ما يفرق بين جرعة متكرّرة وجرعة محظوظة. تحضير وبخار في الوقت نفسه، مع تسخين 30 دقيقة قبل أول فنجان.', 'dual boiler', 'سخّان مزدوج', 185000, 4, array['espresso']::text[], '{"boiler":{"en":"Dual · 1.8 L","ar":"مزدوج · 1.8 لتر"},"pressure":{"en":"9 bar","ar":"9 بار"},"pid":{"en":"±0.3 °C","ar":"±0.3 °م"},"group":{"en":"58 mm","ar":"58 مم"}}'::jsonb, null, null, 'espresso', 'assets/espresso.svg'),
  ('filter-brewer', 'machines', 'brewer', 16, 'Batch brewer', 'مكينة تقطير', 'Filter brewer', 'تقطير', 'Batch brewers that hold 93 °C and shower evenly.', 'مكائن دفعات تثبّت 93 °م وتوزّع الماء بانتظام.', 'What we run on the bar for filter by the cup. A six-jet shower head wets the whole bed at once, and the brew stays inside 92–96 °C for the full cycle.', 'هذه ما نشغّلها على البار للتقطير بالفنجان. موزّع بستّ فتحات يبلّل القاع كله دفعة واحدة، وتبقى الحرارة بين 92 و96 °م طوال الدورة.', '1.9 L', '١٫٩ لتر', 95000, 5, array['filter']::text[], '{"batch":{"en":"1.9 L · 12 cups","ar":"1.9 لتر · 12 فنجاناً"},"temp":{"en":"92–96 °C","ar":"92–96 °م"},"shower":{"en":"6-jet head","ar":"موزّع بست فتحات"}}'::jsonb, null, null, null, 'assets/brewer.svg'),
  ('electric-grinder', 'machines', 'burr', 17, 'Electric burr grinder', 'مطحنة كهربائية', 'Grinder', 'مطحنة', 'Flat and conical burrs, stepless from espresso to French press.', 'مطاحن مسطحة ومخروطية، تدريج مستمر من الإسبريسو إلى الفرنسية.', 'Stepless adjustment, so you can chase a shot by a hair rather than a whole click. Single-dose it and it retains under half a gram.', 'تدريج مستمر، فتضبط الجرعة بفروق دقيقة لا بنقرة كاملة. مع الجرعة المفردة يبقى فيها أقل من نصف غرام.', '64 mm flat', 'مسطحة ٦٤ مم', 68000, 7, array['grinding']::text[], '{"burrs":{"en":"64 mm flat steel","ar":"مسطحة فولاذ 64 مم"},"adjust":{"en":"Stepless","ar":"مستمر"},"rpm":{"en":"1350 rpm","ar":"1350 دورة/دقيقة"}}'::jsonb, null, null, 'grinder', 'assets/burr.svg')
